import React, { useState, useEffect } from 'react';
import { Select } from 'antd';
import { sources } from './data/sources';
import './SourcesExcludedInput.css';

const SourcesExcludedInput = ({ value = [], onChange }) => {
  // Convert sources array to options format for Select
  const sourceOptions = sources.map(source => ({
    value: source.iata,
    label: (
      <div className="flex items-center gap-2">
        <img 
          src={`/airlines/${source.iata.toLowerCase()}.png`}
          alt={source.airline}
          className="h-5 w-8 object-contain"
          onError={(e) => {
            e.target.src = '/airlines/default.png';
          }}
        />
        <span>{source.airline}</span>
      </div>
    )
  }));

  const handleChange = (selectedValues) => {
    onChange?.(selectedValues);
  };

  return (
    <Select
      mode="multiple"
      allowClear
      style={{ width: '100%' }}
      placeholder="Select airlines to exclude"
      value={value}
      onChange={handleChange}
      options={sourceOptions}
      optionFilterProp="children"
      filterOption={(input, option) => {
        const source = sources.find(s => s.iata === option.value);
        if (!source) return false;
        
        const searchText = input.toLowerCase();
        return (
          source.airline.toLowerCase().includes(searchText) ||
          source.iata.toLowerCase().includes(searchText) ||
          source.ffname.toLowerCase().includes(searchText)
        );
      }}
      className="sources-excluded-select"
    />
  );
};

export default SourcesExcludedInput;
